import{_ as a,H as t,f as i,i as s}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"08 | 如何用Nightingale解决Prometheus的告警管理问题？","description":"","frontmatter":{},"headers":[{"level":2,"title":"夜莺简介","slug":"夜莺简介","link":"#夜莺简介","children":[]},{"level":2,"title":"部署夜莺","slug":"部署夜莺","link":"#部署夜莺","children":[]},{"level":2,"title":"告警管理","slug":"告警管理","link":"#告警管理","children":[{"level":3,"title":"规则管理","slug":"规则管理","link":"#规则管理","children":[]},{"level":3,"title":"规则配置","slug":"规则配置","link":"#规则配置","children":[]},{"level":3,"title":"告警屏蔽","slug":"告警屏蔽","link":"#告警屏蔽","children":[]},{"level":3,"title":"告警订阅","slug":"告警订阅","link":"#告警订阅","children":[]},{"level":3,"title":"历史告警存档","slug":"历史告警存档","link":"#历史告警存档","children":[]},{"level":3,"title":"活跃告警聚合","slug":"活跃告警聚合","link":"#活跃告警聚合","children":[]},{"level":3,"title":"告警自愈","slug":"告警自愈","link":"#告警自愈","children":[]},{"level":3,"title":"失联告警","slug":"失联告警","link":"#失联告警","children":[]}]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"互动时刻","slug":"互动时刻","link":"#互动时刻","children":[]}],"relativePath":"运维监控系统实战笔记/08｜如何用Nightingale解决Prometheus的告警管理问题？.md","filePath":"运维监控系统实战笔记/08｜如何用Nightingale解决Prometheus的告警管理问题？.md","lastUpdated":1795561216000}'),n={name:"运维监控系统实战笔记/08｜如何用Nightingale解决Prometheus的告警管理问题？.md"};function r(l,e,h,o,p,g){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="_08-如何用nightingale解决prometheus的告警管理问题" tabindex="-1">08 | 如何用Nightingale解决Prometheus的告警管理问题？ <a class="header-anchor" href="#_08-如何用nightingale解决prometheus的告警管理问题" aria-label="Permalink to &quot;08 | 如何用Nightingale解决Prometheus的告警管理问题？&quot;">​</a></h1><p>你好，我是秦晓辉。上一讲我们聊到了 Prometheus 的存储问题，并提出了 3 种增强方案，这一讲我们继续关注 Prometheus 的另一个问题——告警管理。</p><p>Prometheus 的告警规则、记录规则都是采用配置文件的方式管理的，非常适合奉行Infrastructure as Code 的公司或团队内部使用。但如果要把监控能力开放给全公司，就需要有较好的支持协同操作的 UI，让各个团队互不干扰的同时共享一些通用的成果。</p><p>解决这个需求的开源产品，有两款备选，一个是 Grafana，另一个是夜莺（Nightingale）。Grafana 擅长可视化，是监控绘图领域事实上的标准，而夜莺的侧重点是告警管理，所以这一讲我们重点来介绍一下夜莺，我们可以通过夜莺搭建公司级的监控系统，把监控告警能力赋予公司所有的团队。</p><h2 id="夜莺简介" tabindex="-1">夜莺简介 <a class="header-anchor" href="#夜莺简介" aria-label="Permalink to &quot;夜莺简介&quot;">​</a></h2><p>夜莺最初是滴滴开源的，之后捐赠给了中国计算机学会开源发展委员会（CCF ODC），目标是整合云原生开源生态的众多能力，为用户提供开箱即用、一体化全方位的云原生监控解决方案。</p><p>注：点击查看夜莺的 GitHub 地址和文档地址</p><p>我们先来看一下夜莺的架构，对夜莺的工作模式有个基本的认识。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/08/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/08/1.png" alt=""></a></p><ul><li>夜莺的单机部署架构（图片源自Nightingale官网）</li></ul><p>左下角 Agents 表示监控数据采集器，夜莺可以对接多种 Agent，比如 Categraf、Telegraf、Grafana-Agent、Datadog-Agent。这些 Agent 都是 PUSH 模型，周期性采集监控数据，然后推给 Server 的 HTTP 接口。</p><p>Server 接收到数据之后，会通过 Remote Write 协议把数据转发给时序库，这里时序库使用的</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>是 Prometheus，Prometheus 要想接收 Remote Write 协议的数据，需要在启动参数中开启 -</span></span>
<span class="line"><span>-enable-feature=remote-write-receiver。除了 Prometheus，也可以使用 M3DB、</span></span></code></pre></div><p>VictoriaMetrics、Thanos 等作为时序库。</p><p>Server 的职能相当于一个 Pushgateway，同时也是一个告警引擎，它会周期性地从 MySQL中同步告警规则，做规则判断生成告警事件并发送，对标 Prometheus 的告警引擎和Alertmanager 模块。Server 还会往 Redis 发送心跳信息，不过后面的版本有计划下掉Redis，直接使用 MySQL 处理心跳。</p><p>Webapi 模块提供 HTTP 接口，与前端 JavaScript 交互，主要有两个功能，一个是响应管理请求，比如告警规则、屏蔽规则、监控大盘的增删改查；一个是响应时序数据查询，作为一个Proxy 把请求转发给后面的时序库，等时序库返回结果之后再转发给前端。</p><p>如果有些监控数据是使用 Exporter 采集的，就需要 PULL 模型的采集支持。通常有 3 种做法，一种是直接使用 Prometheus 本身，配置 Scrape 规则；也可以单独部署一个 agentmode 模式的 Prometheus 作为抓取器，和时序库的职能做进程级别的拆分；还可以使用其他支持 PULL 模式的抓取器，比如 Categraf、Grafana-Agent。</p><h2 id="部署夜莺" tabindex="-1">部署夜莺 <a class="header-anchor" href="#部署夜莺" aria-label="Permalink to &quot;部署夜莺&quot;">​</a></h2><p>了解了夜莺的架构之后，下面我们简单聊一下如何部署夜莺，最简单的方式是使用 Dockercompose，一行命令就能搞定。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/ccfos/nightingale.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker-compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>浏览器访问 nwebapi 提供的 18000 端口就能看到登录页面，默认用户是 root，默认密码是root.2020，你如果有 Docker 环境，可以使用这种方式快速部署体验。</p><p>如果你对 Kubernetes 和 Helm 比较熟悉，也可以采用 Helm 的方式部署。当然，最常用的实际是二进制的方式部署，具体步骤你可以参考我给出的链接。</p><p>服务端部署完成之后，我们可以采集一些监控数据看看真实效果，推荐你安装 Categraf。当然，因为夜莺支持多种采集器，你也可以使用其他自己熟悉的采集器。安装完成之后，我们来看一下夜莺具体是如何管理告警的。</p><h2 id="告警管理" tabindex="-1">告警管理 <a class="header-anchor" href="#告警管理" aria-label="Permalink to &quot;告警管理&quot;">​</a></h2><p>Prometheus 的告警管理是在 prometheus.yml 中配置告警规则，在 alertmanager.yml 中配置发送规则，都是需要修改配置文件的，上百人使用的话不太好协同管理。而夜莺提供了 UI 配置能力（当然也有 API），并且在一些方面做了增强，比如更丰富的告警规则配置、历史事件存档、活跃事件聚合查看、对接告警自愈等。下面我们一起来看一下夜莺告警管理的思路。</p><h3 id="规则管理" tabindex="-1">规则管理 <a class="header-anchor" href="#规则管理" aria-label="Permalink to &quot;规则管理&quot;">​</a></h3><p>一个公司可能会有几十上百团队配置成千上万条告警规则，显然不能用一个扁平化的表格来罗列管理，夜莺引入了一个业务组的概念，每一条规则都要归属于某一个业务组，只有这个业务组的人可以管理组内的规则。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/08/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/08/2.png" alt=""></a></p><p>当然，业务组下面不仅有告警规则，还有监控大盘、监控对象、屏蔽规则、订阅规则、告警自愈脚本等等。业务组是夜莺里最重要的一个管理概念。</p><h3 id="规则配置" tabindex="-1">规则配置 <a class="header-anchor" href="#规则配置" aria-label="Permalink to &quot;规则配置&quot;">​</a></h3><p>告警规则的配置，核心还是 PromQL 和持续时长。当然夜莺会有一些额外的增强配置，比如规则的生效时间段、是否仅在本业务组生效、是否启用恢复通知、留观时长、最大发送次数等等。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/08/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/08/3.png" alt=""></a></p><p>夜莺的告警规则是把 PromQL 和发送方式整合到了一条规则中，这个做法和 Alertmanager 是不同的，Prometheus 的告警规则只有 PromQL、持续时长、附加标签、注解这些基本信息，至于发给谁、怎么发，都是在 Alertmanager 中配置的。如何评价这两种方式呢？</p><p>Prometheus+Alertmanager 的方式，可以看做是订阅式，告警规则中不指定接收者，在Alertmanager 的配置中统一设置过滤条件和对应的接收者。这种方式非常灵活，但灵活的东西往往需要定规范，否则容易混乱，比如大家统一按照业务线的标签来做订阅，这就要求时序数据都要打上业务线的标签，或者把业务线的标签放到告警规则的附加标签中，需要付出一些额外的心力。</p><p>Alertmanager 的方式特别适合什么场景呢？就是所有的告警都统一由某一个团队来负责，在这种场景下，Prometheus+Alertmanager 不失为一种最佳实践。</p><ul><li>「讨论」据说 Borgmon 集群和 Borg 集群是一一对应的，那就是说，Borgmon 要处理对应 Borg 集群上的所有应用的告警，不知道在 Borgmon 中是怎么处理告警规则的，如果你了解的话可以留言分享一下。</li></ul><p>夜莺的处理方式和 Datadog 很像，每个团队配置自己的告警规则，发给自己这个团队，即自己管自己的，不需要把告警规则和接收规则拆到两个地方分别配置，我个人觉得更加直观一些，而且夜莺也支持订阅方式，我们后面会介绍。</p><h3 id="告警屏蔽" tabindex="-1">告警屏蔽 <a class="header-anchor" href="#告警屏蔽" aria-label="Permalink to &quot;告警屏蔽&quot;">​</a></h3><p>告警屏蔽这个功能比较简单，是指对一些告警事件做静默处理。对于那些预期内的告警，处理人不希望被打扰就会短时间做一下屏蔽，通常是根据标签对事件做过滤。</p><p>夜莺目前的版本，只能按照时间段屏蔽，比如屏蔽凌晨 0 点到早上 7 点的所有告警，不能做周期性屏蔽，后面的版本会考虑增加这个功能。</p><h3 id="告警订阅" tabindex="-1">告警订阅 <a class="header-anchor" href="#告警订阅" aria-label="Permalink to &quot;告警订阅&quot;">​</a></h3><p>这个机制和 Alertmanager 有点儿像，可以根据告警规则或标签做事件订阅，类似于邮件的抄送功能。</p><p>比如我是业务方，我的业务跑在 Kubernetes 中，Kubernetes 平台如果发生重大故障，我是希望能及时知道的，所以我可以订阅 Kubernetes 的所有严重告警。另外，虽然我希望得知Kubernetes 的严重告警，但我毕竟不是 Kubernetes 的运维人员，所以我在订阅这类事件的时候，不希望用电话这种方式接收告警（太重了），只希望用邮件之类的轻量级方式，所以订阅规则中通常可以重新定义发送媒介、重新定义事件级别。</p><h3 id="历史告警存档" tabindex="-1">历史告警存档 <a class="header-anchor" href="#历史告警存档" aria-label="Permalink to &quot;历史告警存档&quot;">​</a></h3><p>因为夜莺依赖 MySQL 做数据持久化，所以告警事件可以直接存入数据库，所有的历史告警都可以追踪查询。虽然这个功能很简单，但很多企业都需要，在自证清白的时候显得尤为重要。</p><p>当然，所有历史告警存档，也可以用于后续分析，从这些数据中可以轻易得知哪些业务线的告警发送得最多，消耗电话、短信费用最多，哪些业务线的告警解决得最快，哪些人是接收告警的劳模等等。其实也能从侧面反映出这个团队的告警策略需要优化，或者业务稳定性需要优化。</p><h3 id="活跃告警聚合" tabindex="-1">活跃告警聚合 <a class="header-anchor" href="#活跃告警聚合" aria-label="Permalink to &quot;活跃告警聚合&quot;">​</a></h3><p>所谓活跃告警就是未恢复的告警，活跃告警功能很重要，应该作为日常巡检必须要关注的页面。</p><p>为了减少查看的心理负担，便于给告警事件分类，夜莺支持聚合卡片视图，而且聚合规则是可以自定义的，比如当前有 300 条未恢复的告警，我们可以根据告警规则聚合查看，也可以根据地域、业务线、服务、机器等维度聚合查看，一目了然非常方便。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/08/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/08/4.png" alt=""></a></p><h3 id="告警自愈" tabindex="-1">告警自愈 <a class="header-anchor" href="#告警自愈" aria-label="Permalink to &quot;告警自愈&quot;">​</a></h3><p>当告警事件触发之后，能自动触发一个恢复动作来止损，这就是所谓的告警自愈。一般监控系统都会支持 Webhook，告警触发之后自动回调某个接口，我们就可以在这个接口里写一些自动化逻辑，但是这种方式还是要写个 HTTP Server 的，成本略高。夜莺除了支持 Webhook 之外，还可以在告警时自动执行某个脚本，用户就可以直接在脚本里写逻辑了。</p><p>告警自愈依赖 ibex 模块，这是一个批量执行脚本的小工具，你可以安装测试一下。不过有些公司会觉得有安全隐患，不敢开启这个功能，我觉得纯内网环境问题不大，如果开放到公网的话确实需要小心。</p><p>自愈脚本要能够在机器上运行，需要有较强的权限管控，这个权限也是依赖业务组的机制，只有这个业务组的管理人员，才能去这个组内的机器上跑脚本。夜莺里有个对象管理，主要就是管机器的，设计对象管理功能很重要的一个原因就是为了支持告警自愈。</p><h3 id="失联告警" tabindex="-1">失联告警 <a class="header-anchor" href="#失联告警" aria-label="Permalink to &quot;失联告警&quot;">​</a></h3><p>夜莺主要是用推模式来接收监控数据，所以如何感知监控对象失联是个比较麻烦的问题。PromQL 中有 absent 函数，但是这个函数使用起来非常麻烦，如果要为 100 台机器配置失联告警，就要配置 100 条告警规则，基本无法管理。</p><p>夜莺在服务端加了一个逻辑，接收到监控数据之后，会自动从数据中解析出 ident 标签当做机器标识，然后为这个机器生成 target_up 指标。这个机器有监控数据上报，则 target_up 的值设置为 1；如果长时间收不到机器的指标上报，则 target_up 的值设置为 0。通过这种方式，只需要配置一条告警规则就可以覆盖所有的监控对象。</p><p>以上就是夜莺所有告警相关的功能，有些人了解了夜莺之后觉得不错，想要去尝试，但是之前很多规则已经用 Prometheus Yaml 文件管理了，感觉迁移起来比较麻烦，就来问我怎么搞比较合适。</p><p>我的观点是这样的：老的 Yaml 文件管理的规则其实可以不用动，甚至如果 Prometheus 只是给自己团队使用的话也不太需要引入夜莺，只有那些想要把监控能力开放给全公司用的场景才需要引入夜莺，而且新规则可以用夜莺管理，老的规则不迁移或者慢慢迁移都是可以的。还是那句话，技术是为了解决现实问题，没有什么非黑即白。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这一讲我们要解决的问题是增强 Prometheus 的告警管理能力，因为 Prometheus 的 Yaml 文件管理方式不太方便做公司级协同管理。Grafana 和夜莺都可以解决这个问题，不过 Grafana更擅长看图，夜莺更擅长告警管理，所以这一讲我们重点讲解了夜莺的告警功能。</p><p>夜莺告警管理能力分三类，一个是规则管理，包括告警规则、屏蔽规则、订阅规则，一个是事件管理，包括历史事件、活跃事件，最后一个是告警自愈。为了方便你理解、记忆，我把这一讲的内容整理成了一张脑图，你可以参考。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/08/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/08/5.png" alt=""></a></p><h2 id="互动时刻" tabindex="-1">互动时刻 <a class="header-anchor" href="#互动时刻" aria-label="Permalink to &quot;互动时刻&quot;">​</a></h2><p>不管是 Prometheus 还是 Nightingale，在告警恢复事件中都无法拿到当前值（告警触发事件中是可以拿到的），很多人觉得不理解，你知道为什么会这样吗？你有办法拿到恢复时候的最新值吗？欢迎你在评论区留言讨论。如果你觉得有收获，也欢迎你把今天的内容分享给你身边的朋友，邀他一起学习。我们下一讲见。</p>`,65)])])}const B=a(n,[["render",r]]);export{u as __pageData,B as default};
